def parse_duration(s):
    import re
    h = re.search(r'(\d+)h', s)
    m = re.search(r'(\d+)m', s)
    seconds = re.search(r'(\d+)s', s)
    return (
        (int(h.group(1)) * 3600 if h else 0)
        + (int(m.group(1)) * 60 if m else 0)
        + (int(seconds.group(1)) if seconds else 0)
    )

