def chunk_even(lst, n):
    if n <= 0:
        return []
    k, remainder = divmod(len(lst), n)
    chunks = []
    start = 0
    for i in range(n):
        end = start + k + (i < remainder)
        chunks.append(lst[start:end])
        start = end
    return chunks

